CREATE TABLE "fastp_qc" (
  "sample" TEXT NOT NULL,
  "tool_version" TEXT,
  "adapter_cutting_adapter_trimmed_bases" REAL,
  "adapter_cutting_adapter_trimmed_reads" REAL,
  "after_filtering_gc_content" REAL,
  "after_filtering_q20_bases" REAL,
  "after_filtering_q20_rate" REAL,
  "after_filtering_q30_bases" REAL,
  "after_filtering_q30_rate" REAL,
  "after_filtering_read1_mean_length" REAL,
  "after_filtering_read2_mean_length" REAL,
  "after_filtering_total_bases" REAL,
  "after_filtering_total_reads" REAL,
  "before_filtering_total_reads" REAL,
  "filtering_result_low_quality_reads" REAL,
  "filtering_result_passed_filter_reads" REAL,
  "filtering_result_too_long_reads" REAL,
  "filtering_result_too_many_N_reads" REAL,
  "filtering_result_too_short_reads" REAL,
  "pct_adapter" REAL,
  "pct_duplication" REAL,
  "pct_surviving" REAL,
  UNIQUE ("sample")
) STRICT;
